pat=[7,7,5,7,5]
placements={}
for r,c in markers:
 for d,v in zip(range(-2,3),pat):
  x=c+d
  if 0<=x<26: placements[(r,x)]=v
print('Placement cells:',len(placements))
for r,c in markers:
 print((r,c),[(c+d,v) for d,v in zip(range(-2,3),pat) if 0<=c+d<26])
print('Rows with placed values:')
for r in sorted(set(x[0] for x in placements)):
 print(r, sorted((c,v) for (rr,c),v in placements.items() if rr==r))
